-- Workspace lifecycle: sign up provisioning, the keep-an-owner rule, slug
-- immutability, own-row profiles, and cascading deletes.
begin;

create extension if not exists pgtap with schema extensions;

select plan(28);

-- Test helpers, rolled back with the transaction.
-- rls_test.affected: rows touched by a statement run as the current role, or -1
-- when Postgres refuses it (42501). A refused write is any result <= 0.
-- rls_test.ids: ids generated by triggers, so impersonated statements can
-- refer to them without hard coding.
create schema rls_test;
grant usage on schema rls_test to anon, authenticated;

create function rls_test.affected(p_sql text)
returns integer
language plpgsql
as $fn$
declare
  v_count integer;
begin
  execute p_sql;
  get diagnostics v_count = row_count;
  return v_count;
exception
  when insufficient_privilege then
    return -1;
end;
$fn$;

grant execute on function rls_test.affected(text) to anon, authenticated;

create table rls_test.ids (key text primary key, id uuid not null, val text);
grant select on rls_test.ids to authenticated;

-- Invite first, mirroring production where the before-user-created hook only
-- lets invited emails through. Inserting into auth.users directly skips the
-- hook (it is an Auth server hook) but fires on_auth_user_created.
insert into public.access_invites (email, invited_by)
values
  ('rls-life-new@example.com', 'pgtap'),
  ('rls-life-other@example.com', 'pgtap');

insert into auth.users (id, instance_id, aud, role, email, raw_user_meta_data, raw_app_meta_data, created_at, updated_at)
values
  ('d0000001-0000-4000-8000-000000000000', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated',
   'rls-life-new@example.com',
   '{"user_name": "rls-life-new", "avatar_url": "https://avatars.example.com/rls-life-new.png"}',
   '{"provider": "github", "providers": ["github"]}', now(), now()),
  ('d0000002-0000-4000-8000-000000000000', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated',
   'rls-life-other@example.com', '{"user_name": "rls-life-other"}',
   '{"provider": "github", "providers": ["github"]}', now(), now());

insert into rls_test.ids (key, id, val)
select 'personal', w.id, w.slug
from public.workspaces w
where w.created_by = 'd0000001-0000-4000-8000-000000000000' and w.is_personal
order by w.created_at
limit 1;

insert into rls_test.ids (key, id)
select 'other_personal', w.id
from public.workspaces w
where w.created_by = 'd0000002-0000-4000-8000-000000000000' and w.is_personal
order by w.created_at
limit 1;

-- ---------------------------------------------------------------------------
-- Sign up provisioning
-- ---------------------------------------------------------------------------
select has_trigger('auth', 'users', 'on_auth_user_created',
  'signup: auth.users has the on_auth_user_created trigger');

select is(
  (select count(*)::integer from public.workspaces
   where created_by = 'd0000001-0000-4000-8000-000000000000' and is_personal),
  1,
  'signup: a new auth user gets exactly one personal workspace');

select results_eq(
  $$ select name, is_personal from public.workspaces where id = (select id from rls_test.ids where key = 'personal') $$,
  $$ values ('Personal'::text, true) $$,
  'signup: the personal workspace is named Personal and flagged is_personal');

select matches(
  (select val from rls_test.ids where key = 'personal'),
  '^[a-z0-9]{10}$',
  'signup: the personal workspace slug is random, 10 lowercase characters, not derived from the name');

select results_eq(
  $$ select workspace_id, role::text from public.workspace_members where user_id = 'd0000001-0000-4000-8000-000000000000' $$,
  $$ select id, 'owner'::text from rls_test.ids where key = 'personal' $$,
  'signup: the new user is the owner and only member of their personal workspace');

select results_eq(
  $$ select display_name, avatar_url, last_workspace_id from public.profiles where user_id = 'd0000001-0000-4000-8000-000000000000' $$,
  $$ select 'rls-life-new'::text, 'https://avatars.example.com/rls-life-new.png'::text, id from rls_test.ids where key = 'personal' $$,
  'signup: the profile takes user_name and avatar_url and points last_workspace_id at the personal workspace');

-- Idempotency: replay the real trigger function for the same user by
-- attaching it to a scratch copy of auth.users and inserting the same row.
-- A second delivery must not create a second workspace, membership, or profile.
create table rls_test.users_replay (like auth.users);

do $replay$
begin
  execute format(
    'create trigger replay_on_auth_user_created after insert on rls_test.users_replay for each row execute function %s()',
    (select t.tgfoid::regproc::text
     from pg_catalog.pg_trigger t
     where t.tgrelid = 'auth.users'::regclass and t.tgname = 'on_auth_user_created')
  );
end;
$replay$;

insert into rls_test.users_replay
select * from auth.users where id = 'd0000001-0000-4000-8000-000000000000';

select results_eq(
  $$
    select
      (select count(*)::integer from public.workspaces where created_by = 'd0000001-0000-4000-8000-000000000000' and is_personal),
      (select count(*)::integer from public.workspace_members where user_id = 'd0000001-0000-4000-8000-000000000000'),
      (select count(*)::integer from public.profiles where user_id = 'd0000001-0000-4000-8000-000000000000')
  $$,
  $$ values (1, 1, 1) $$,
  'signup idempotent: running on_auth_user_created twice still leaves one workspace, one membership, one profile');

-- create_workspace (service role path) inserts the workspace and the owner
-- membership together.
insert into rls_test.ids (key, id)
select 'team', w.id
from public.create_workspace('d0000001-0000-4000-8000-000000000000', 'Lifecycle team', false) as w;

select results_eq(
  $$
    select m.user_id, m.role::text, w.is_personal
    from public.workspace_members m
    join public.workspaces w on w.id = m.workspace_id
    where m.workspace_id = (select id from rls_test.ids where key = 'team')
  $$,
  $$ values ('d0000001-0000-4000-8000-000000000000'::uuid, 'owner'::text, false) $$,
  'create_workspace: creates a non-personal workspace with the caller as its only owner');

-- ---------------------------------------------------------------------------
-- Profiles: own row only
-- ---------------------------------------------------------------------------
set local role authenticated;
set local request.jwt.claims to '{"sub": "d0000001-0000-4000-8000-000000000000", "role": "authenticated"}';

select isnt_empty($$ select user_id from public.profiles where user_id = 'd0000001-0000-4000-8000-000000000000' $$,
  'profiles: a user can select their own profile');
select is_empty($$ select user_id from public.profiles where user_id = 'd0000002-0000-4000-8000-000000000000' $$,
  'profiles: a user cannot select another user''s profile');
select is(rls_test.affected($$ update public.profiles set display_name = 'Renamed self' where user_id = 'd0000001-0000-4000-8000-000000000000' $$), 1,
  'profiles: a user can update their own profile');
select cmp_ok(rls_test.affected($$ update public.profiles set display_name = 'Renamed other' where user_id = 'd0000002-0000-4000-8000-000000000000' $$), '<=', 0,
  'profiles: a user cannot update another user''s profile');
-- last_workspace_id may only name a workspace the user belongs to. The app treats the refusal
-- (42501) as expected, so a policy that refused members would go unnoticed without this pair.
select is(rls_test.affected($$ update public.profiles set last_workspace_id = (select id from rls_test.ids where key = 'team')
    where user_id = 'd0000001-0000-4000-8000-000000000000' $$), 1,
  'profiles: a user can point last_workspace_id at a workspace they belong to');
select is(rls_test.affected($$ update public.profiles set last_workspace_id = (select id from rls_test.ids where key = 'other_personal')
    where user_id = 'd0000001-0000-4000-8000-000000000000' $$), -1,
  'profiles: pointing last_workspace_id at a workspace the user does not belong to is refused with 42501');

reset role;
reset request.jwt.claims;

-- ---------------------------------------------------------------------------
-- A workspace must keep at least one owner. The rule is a deferred constraint
-- trigger, so force it to fire at statement end instead of at commit (these
-- tests never commit).
-- ---------------------------------------------------------------------------
set constraints all immediate;

select throws_ok(
  $$
    delete from public.workspace_members
    where workspace_id = (select id from rls_test.ids where key = 'personal')
      and user_id = 'd0000001-0000-4000-8000-000000000000'
  $$,
  null::char(5), null::text,
  'last owner: removing the only owner membership fails, even for the service role');

select throws_ok(
  $$
    update public.workspace_members set role = 'admin'
    where workspace_id = (select id from rls_test.ids where key = 'personal')
      and user_id = 'd0000001-0000-4000-8000-000000000000'
  $$,
  null::char(5), null::text,
  'last owner: demoting the only owner fails, even for the service role');

set local role authenticated;
set local request.jwt.claims to '{"sub": "d0000001-0000-4000-8000-000000000000", "role": "authenticated"}';

select throws_ok(
  $$
    delete from public.workspace_members
    where workspace_id = (select id from rls_test.ids where key = 'personal')
      and user_id = 'd0000001-0000-4000-8000-000000000000'
  $$,
  null::char(5), null::text,
  'last owner: the only owner cannot leave their own workspace');

reset role;
reset request.jwt.claims;

select results_eq(
  $$
    select role::text from public.workspace_members
    where workspace_id = (select id from rls_test.ids where key = 'personal')
  $$,
  $$ values ('owner'::text) $$,
  'last owner: the owner membership survives every rejected attempt');

-- Control: with a second owner present, removing one owner is allowed, so the
-- rule targets the last owner and not owners in general.
insert into public.workspace_members (workspace_id, user_id, role)
select id, 'd0000002-0000-4000-8000-000000000000', 'owner' from rls_test.ids where key = 'team';

select lives_ok(
  $$
    delete from public.workspace_members
    where workspace_id = (select id from rls_test.ids where key = 'team')
      and user_id = 'd0000002-0000-4000-8000-000000000000'
  $$,
  'last owner: removing one of two owners succeeds');

-- ---------------------------------------------------------------------------
-- Slugs are immutable; names are not, and renaming never touches the slug.
-- ---------------------------------------------------------------------------
select throws_ok(
  $$ update public.workspaces set slug = 'abcdefghij' where id = (select id from rls_test.ids where key = 'personal') $$,
  null::char(5), null::text,
  'slug immutable: updating a workspace slug fails, even for the service role');

set local role authenticated;
set local request.jwt.claims to '{"sub": "d0000001-0000-4000-8000-000000000000", "role": "authenticated"}';

select throws_ok(
  $$ update public.workspaces set slug = 'abcdefghij' where id = (select id from rls_test.ids where key = 'personal') $$,
  null::char(5), null::text,
  'slug immutable: the owner cannot update their workspace slug');

select is(rls_test.affected($$ update public.workspaces set name = 'Renamed personal' where id = (select id from rls_test.ids where key = 'personal') $$), 1,
  'slug immutable: the owner can rename their workspace');

reset role;
reset request.jwt.claims;

select is(
  (select slug from public.workspaces where id = (select id from rls_test.ids where key = 'personal')),
  (select val from rls_test.ids where key = 'personal'),
  'slug immutable: the slug is unchanged after the rejected updates and the rename');

-- ---------------------------------------------------------------------------
-- Deleting a workspace as its owner cascades to every tenant table.
-- ---------------------------------------------------------------------------
insert into public.projects (id, workspace_id, name)
select 'd00000b1-0000-4000-8000-000000000000', id, 'Cascade project' from rls_test.ids where key = 'team';

insert into public.connections (id, workspace_id, provider, status, display_name, poll_interval_seconds)
select 'd00000b2-0000-4000-8000-000000000000', id, 'fake', 'active', 'Cascade connection', 3600 from rls_test.ids where key = 'team';

insert into public.connection_credentials (connection_id, workspace_id, key_id, iv, ciphertext, auth_tag)
select 'd00000b2-0000-4000-8000-000000000000', id, 'deadbeef', '\x00'::bytea, '\x01'::bytea, '\x02'::bytea from rls_test.ids where key = 'team';

insert into public.oauth_states (state, workspace_id, provider, user_id, expires_at)
select 'rls-life-cascade-state', id, 'fake', 'd0000001-0000-4000-8000-000000000000', now() + interval '10 minutes'
from rls_test.ids where key = 'team';

insert into public.external_accounts (id, workspace_id, connection_id, external_id, display_name, kind, project_id)
select 'd00000b3-0000-4000-8000-000000000000', id, 'd00000b2-0000-4000-8000-000000000000', 'ext-cascade', 'Cascade account', 'team',
       'd00000b1-0000-4000-8000-000000000000'
from rls_test.ids where key = 'team';

insert into public.usage_snapshots (
  id, workspace_id, connection_id, external_account_id, metric_key, kind, label, snapshot_date,
  amount_minor, currency, period_start, period_end, retrieved_at, provenance_source
)
select 'd00000b4-0000-4000-8000-000000000000', id, 'd00000b2-0000-4000-8000-000000000000', 'd00000b3-0000-4000-8000-000000000000',
       'fake.spend', 'verified_spend', 'Cascade snapshot', date '2026-10-01',
       700, 'GBP', timestamptz '2026-10-01 00:00:00+00', timestamptz '2026-11-01 00:00:00+00', now(), 'provider_api'
from rls_test.ids where key = 'team';

insert into public.activity_events (id, workspace_id, connection_id, provider, type_id, severity, title, occurred_at, dedupe_key)
select 'd00000b5-0000-4000-8000-000000000000', id, 'd00000b2-0000-4000-8000-000000000000', 'fake', 'fake.deployment', 'success',
       'Cascade event', now(), 'rls-life-cascade-event'
from rls_test.ids where key = 'team';

insert into public.budgets (id, workspace_id, name, scope, amount_minor, currency)
select 'd00000b6-0000-4000-8000-000000000000', id, 'Cascade budget', 'workspace', 5000, 'GBP' from rls_test.ids where key = 'team';

insert into public.alert_rules (id, workspace_id, kind, scope, budget_id, threshold_percent)
select 'd00000b7-0000-4000-8000-000000000000', id, 'budget_percent', 'workspace', 'd00000b6-0000-4000-8000-000000000000', 75
from rls_test.ids where key = 'team';

insert into public.triggered_alerts (id, workspace_id, rule_id, cycle_key, threshold_label, is_estimated, message)
select 'd00000b8-0000-4000-8000-000000000000', id, 'd00000b7-0000-4000-8000-000000000000', '2026-10-01', '75%', false, 'Cascade alert'
from rls_test.ids where key = 'team';

insert into public.sync_jobs (id, workspace_id, connection_id, kind, dedupe_key)
select 'd00000b9-0000-4000-8000-000000000000', id, 'd00000b2-0000-4000-8000-000000000000', 'sync', 'rls-life-cascade-sync'
from rls_test.ids where key = 'team';

update public.profiles
set last_workspace_id = (select id from rls_test.ids where key = 'team')
where user_id = 'd0000001-0000-4000-8000-000000000000';

set local role authenticated;
set local request.jwt.claims to '{"sub": "d0000001-0000-4000-8000-000000000000", "role": "authenticated"}';

select is(rls_test.affected($$ delete from public.workspaces where id = (select id from rls_test.ids where key = 'team') $$), 1,
  'workspace delete: the owner can delete their workspace');

reset role;
reset request.jwt.claims;

-- Lists every table that still holds a row for the deleted workspace.
select is_empty(
  $$
    with team as (select id from rls_test.ids where key = 'team')
    select 'workspaces' from public.workspaces where id = (select id from team)
    union all select 'workspace_members' from public.workspace_members where workspace_id = (select id from team)
    union all select 'projects' from public.projects where workspace_id = (select id from team)
    union all select 'connections' from public.connections where workspace_id = (select id from team)
    union all select 'connection_credentials' from public.connection_credentials where workspace_id = (select id from team)
    union all select 'oauth_states' from public.oauth_states where workspace_id = (select id from team)
    union all select 'external_accounts' from public.external_accounts where workspace_id = (select id from team)
    union all select 'usage_snapshots' from public.usage_snapshots where workspace_id = (select id from team)
    union all select 'activity_events' from public.activity_events where workspace_id = (select id from team)
    union all select 'activity_event_daily_counts' from public.activity_event_daily_counts where workspace_id = (select id from team)
    union all select 'budgets' from public.budgets where workspace_id = (select id from team)
    union all select 'alert_rules' from public.alert_rules where workspace_id = (select id from team)
    union all select 'triggered_alerts' from public.triggered_alerts where workspace_id = (select id from team)
    union all select 'sync_jobs' from public.sync_jobs where workspace_id = (select id from team)
  $$,
  'workspace delete: deleting a workspace cascades to every tenant and service only table');

select is(
  (select last_workspace_id from public.profiles where user_id = 'd0000001-0000-4000-8000-000000000000'),
  null::uuid,
  'workspace delete: profiles.last_workspace_id pointing at the deleted workspace is set to null');

-- Deleting an auth user removes the workspaces they were the only member of.
delete from auth.users where id = 'd0000002-0000-4000-8000-000000000000';

select is_empty(
  $$ select id from public.workspaces where id = (select id from rls_test.ids where key = 'other_personal') $$,
  'user delete: deleting an auth user removes the personal workspace they alone belonged to');

select is_empty(
  $$ select user_id from public.profiles where user_id = 'd0000002-0000-4000-8000-000000000000' $$,
  'user delete: deleting an auth user removes their profile');

select * from finish();

rollback;
